#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int a[105];
    int max_val = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        if (a[i] > max_val) {
            max_val = a[i];
        }
    }

    int phases = 0;

    while (1) {
        int min_val = max_val;
        for (int i = 0; i < n; i++) {
            if (a[i] < min_val) {
                min_val = a[i];
            }
        }

        if (min_val == max_val) {
            break;
        }

        int i = 0;
        while (i < n) {
            if (a[i] == min_val) {
                phases++;
                int j = i;
                while (j < n && a[j] == min_val) {
                    a[j]++;
                    j++;
                }
                i = j;
            } else {
                i++;
            }
        }
    }

    printf("%d\n", phases);

    return 0;
}
